public abstract record ConnectionState
{
    private ConnectionState() { }                 // closes the hierarchy
    public sealed record Disconnected : ConnectionState;
    public sealed record Connecting(DateTimeOffset Initiated) : ConnectionState;
    public sealed record Connected(string SessionId) : ConnectionState;
}

var summary = state switch
{
    ConnectionState.Connected c => c.SessionId,
    ConnectionState.Connecting c => $"connecting since {c.Initiated}",
    ConnectionState.Disconnected => "down",
};   // CS8509 warns when a variant is missing: treat warnings as errors

