public record Disconnected;
public record Connecting(DateTimeOffset Initiated);
public record Connected(string SessionId);

public union ConnectionState(Disconnected, Connecting, Connected);   // closed set

string Describe(ConnectionState s) => s switch
{
    Disconnected => "down",
    Connecting c => $"connecting since {c.Initiated}",
    Connected c  => c.SessionId,       // no discard arm needed
};
